SINA_SMART["hemato1-transfusion"] = {"lecture":"hemato1-transfusion","title":"Blood groups and transfusion","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-transfusion:e0","text":"Blood group: inherited red cell surface antigens (glycoproteins or glycolipids).","topic":"Blood groups: definitions","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e1","text":"About 40 systems; ABO, Rh and Kell matter most for transfusion.","topic":"Blood groups: definitions","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e2","text":"ABO antibodies: natural and regular IgM; appear at 3-4 months.","topic":"Blood groups: definitions","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e3","text":"Group A: anti-B; B: anti-A; AB: none; O: anti-A + anti-B.","topic":"The ABO system (ISBT 001)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e4","text":"ABO genes on chromosome 9; A and B co-dominant, O recessive.","topic":"The ABO system (ISBT 001)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e5","text":"Rh D positive 85%; anti-D is immune IgG, crosses the placenta (HDN).","topic":"Rhesus and Kell","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e6","text":"K: most immunogenic after ABO and D.","topic":"Rhesus and Kell","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e7","text":"ABO typing: Beth-Vincent (antigens) + Simonin (antibodies); two typings.","topic":"Blood typing","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e8","text":"Never give an antigen the recipient lacks; O universal donor, AB universal recipient.","topic":"Transfusion compatibility rules","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e10","text":"Leukoreduction: febrile reactions, HLA, CMV. Irradiation: TA-GVHD. Washing: IgA deficiency.","topic":"Blood donation and blood components","sec":5,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-transfusion:e9","text":"RBC 42 days +4 °C; platelets 5 days 22 °C; FFP 1 year -30 °C.","topic":"Blood donation and blood components","sec":5,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"15zdcdj":"a","1ga9fjb":"a","d4g5zu":"a","1qhut7w":"a","29v63e":"a","tz2h5m":"a","o3hi91":"a","1jfafi4":"a","njd6zr":"a","36kjiq":"a","k8d0bn":"a","1iq30w4":"a","kp18se":"a","16a7n5x":"a","n0xuyp":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-transfusion:e0":{"s":0,"u":["Blood group: inherited red cell surface antigens (glycoproteins or glycolipids).","A blood group is an inherited classification based on the presence or absence of antigens on the red cell surface .","These antigens are carbohydrates attached to proteins or lipids (glycoproteins, glycolipids) and are recognised by specific antibodies."],"dp":[]},"hemato1-transfusion:e1":{"s":0,"u":["About 40 systems; ABO, Rh and Kell matter most for transfusion.","There are about 40 systems and 370 antigens , each system independent of the others; the three that must be respected in transfusion are ABO, Rhesus (RH) and Kell (KEL) ."],"dp":[]},"hemato1-transfusion:e2":{"s":0,"u":["ABO antibodies: natural and regular IgM; appear at 3-4 months.","Antibodies can be natural (present without exposure to foreign red cells, IgM) and regular (always present when the antigen is absent), or immune : they appear after immunisation by transfusion or pregnancy and are IgG."],"dp":[]},"hemato1-transfusion:e3":{"s":1,"u":["Group A: anti-B; B: anti-A; AB: none; O: anti-A + anti-B.","Two antigens give four groups: A (antigen A, anti-B in plasma), B (antigen B, anti-A), AB (both antigens, no antibody) and O (neither antigen, anti-A and anti-B).","ABO antigens are also tissue antigens (platelets, white cells, endothelium, secretions) and exist on bacteria and plants, which explains why anti-A and anti-B are natural."],"dp":[]},"hemato1-transfusion:e4":{"s":1,"u":["ABO genes on chromosome 9; A and B co-dominant, O recessive.","Genes on chromosome 9 : A and B are co-dominant , O is recessive.","Gene H adds fucose to a precursor (substance H = the 'O antigen'); gene A adds N-acetylgalactosamine, gene B adds galactose."],"dp":[]},"hemato1-transfusion:e5":{"s":2,"u":["Rh D positive 85%; anti-D is immune IgG, crosses the placenta (HDN).","Anti-D is not natural : it is an immune IgG made by a D-negative person after D-positive red cells (transfusion or pregnancy) and crosses the placenta , causing haemolytic disease of the newborn in a later D-positive fetus; this is why it is prevented.","D present = Rh positive (85%) ; absent = Rh negative (15%)."],"dp":[]},"hemato1-transfusion:e6":{"s":2,"u":["K: most immunogenic after ABO and D.","K is the most immunogenic antigen after ABO and D.","Rhesus (ISBT 004) is the second most important system; its antigens are red-cell specific and highly immunogenic, especially D ."],"dp":[]},"hemato1-transfusion:e7":{"s":3,"u":["ABO typing: Beth-Vincent (antigens) + Simonin (antibodies); two typings.","ABO typing needs two tests : the Beth-Vincent test (patient red cells + test sera anti-A, anti-B: finds the antigens) and the Simonin test (patient plasma + test red cells A and B: finds the antibodies).","Molecular (genetic) typing is also possible."],"dp":[]},"hemato1-transfusion:e8":{"s":4,"u":["Never give an antigen the recipient lacks; O universal donor, AB universal recipient.","So O is the universal red cell donor and AB the universal recipient .","In a life-threatening emergency, never give an antigen the recipient lacks (it would meet the corresponding antibody)."],"dp":[{"h":"Why O plasma is not universal","t":"The 'universal donor' rule applies to red cells : O red cells lack A and B, so the recipient's antibodies have nothing to attack. For plasma the logic reverses, because what is transfused is the donor's antibodies. O plasma contains anti-A and anti-B and could haemolyse an A, B or AB recipient's cells, whereas AB plasma , with no ABO antibodies, is the universal plasma. Same principle, applied to whatever the component carries. Source: the lecture's compatibility rules, extended to plasma."}]},"hemato1-transfusion:e10":{"s":5,"u":["Leukoreduction: febrile reactions, HLA, CMV. Irradiation: TA-GVHD. Washing: IgA deficiency.","Transformations: leukoreduction (&gt; 99% of white cells removed by filtration: prevents febrile reactions, HLA alloimmunisation, CMV), irradiation (25-45 Gy, prevents transfusion-associated GVHD), paediatric splitting, washing (severe allergy, IgA deficiency with anti-IgA).","Qualifications: extended phenotype, CMV-negative , HLA or HPA compatible."],"dp":[]},"hemato1-transfusion:e9":{"s":5,"u":["RBC 42 days +4 °C; platelets 5 days 22 °C; FFP 1 year -30 °C.","Centrifugation separates components: red cell concentrate (42 days, +4 °C; anaemia), platelet concentrate (5 days, 22 °C with agitation; 6-8 pooled for an adult) or a single-donor apheresis unit (≈ 5 pooled concentrates, fewer viral and alloimmunisation risks), and fresh frozen plasma (1 year, -30 °C; coagulation factors)."],"dp":[]}},"meta":{"15zdcdj":{"a":"recall","vg":"hemato1-transfusion:e3/recall/1"},"1ga9fjb":{"a":"recall","vg":"hemato1-transfusion:e2/recall/1"},"d4g5zu":{"a":"recall","vg":"hemato1-transfusion:e5/recall/1"},"1qhut7w":{"a":"recall","vg":"hemato1-transfusion:e8/recall/1"},"29v63e":{"a":"recall","vg":"hemato1-transfusion:e8/recall/1"},"tz2h5m":{"a":"recall","vg":"hemato1-transfusion:e7/recall/1"},"o3hi91":{"a":"recall","vg":"hemato1-transfusion:e7/recall/2"},"1jfafi4":{"a":"recall","vg":"hemato1-transfusion:e4/recall/1"},"njd6zr":{"a":"recall","vg":"hemato1-transfusion:e6/recall/1"},"36kjiq":{"a":"recall","vg":"hemato1-transfusion:e5/recall/2"},"k8d0bn":{"a":"recall","vg":"hemato1-transfusion:e9/recall/1"},"1iq30w4":{"a":"recall","vg":"hemato1-transfusion:e9/recall/1"},"kp18se":{"a":"recall","vg":"hemato1-transfusion:e10/recall/1"},"16a7n5x":{"a":"recall","vg":"hemato1-transfusion:e10/recall/2"},"n0xuyp":{"a":"recall","vg":"hemato1-transfusion:e8/recall/2"}},"explRev":"21a7c12a7e8e"};
